const SV_PEER_SECTOR = {hydro: 'Hydro Power', cbank: 'Commercial Banks', dbank: 'Development Banks', finance: 'Finance', mfi: 'Microfinance', nonlife: 'Non Life Insurance', life: 'Life Insurance', trading: 'Tradings', mfg: 'Manufacturing And Processing'};
const svF = (v, d = 2) => isNum(v) ? fmt(v, d) : '–';
const svMn = v => isNum(v) ? fmt(v / 1e6, 1) : '–';
function svFund(sym) { const fd = ds('stock_fundamentals'); return fd ? fd.rows.filter(r => r.symbol === sym).sort((a, b) => a.asof < b.asof ? -1 : 1).pop() : null; }
