const svIn = (k, l, v, hint = '') => `<div class="f"><label for="sv_${k}" title="${esc(hint)}">${l}</label><input id="sv_${k}" data-sv="${k}" value="${isNum(v) ? +(+v).toFixed(6) : esc(v ?? '')}"></div>`;
const svSel = (k, l, v, opts) => `<div class="f"><label for="sv_${k}">${l}</label><select id="sv_${k}" data-sv="${k}">${opts.map(([a, b]) => `<option value="${a}" ${String(a) === String(v) ? 'selected' : ''}>${b}</option>`).join('')}</select></div>`;
