/* ================= shared helpers for financial-statement based sectors ================= */
function svItems() { const S = RP.st, I = S?.items || {}, U = S?.unit || 1; const v = (k, w = 'cur') => isNum(I[k]?.[w]) ? I[k][w] * U : null; return {v, S, U, mined: S?.mined || {}}; }
function svMarket(sym) { const fr = svFund(sym), {v, S} = svItems(); const sh = RP.shares || S?.mined?.shares || (isNum(v('share_capital')) ? v('share_capital') / 100 : null);
  const price = (() => { try { return qSymbols().includes(sym) ? last(qSeries(sym).c) : fr?.ltp ?? null; } catch (e) { return fr?.ltp ?? null; } })();
  let beta = 1; try { if (qSymbols().includes(sym) && sym !== 'NEPSE') { const A = sqAligned([sym, 'NEPSE'], 750); if (A.R.length > 120) beta = Math.max(0.4, Math.min(2, ST.ols(A.R.map(x => x[0]), A.R.map(x => [1, x[1]])).coef[1])); } } catch (e) {}
  return {fr, sh, price, beta, rf: sqRf()}; }
// value-per-share helpers shared by banks and insurers
function svEquityModels(P, A, sh) { // P: rows {NP, E0 (opening equity), E (closing), Div}; A: ke, gT, omega
  const ke = A.ke / 100, gT = A.gT / 100, n = P.length; let pvRI = 0, pvDiv = 0;
  P.forEach((r, i) => { const d = Math.pow(1 + ke, i + 1); r.RI = r.NP - ke * r.E0; pvRI += r.RI / d; pvDiv += r.Div / d; });
  const L = P[n - 1], omega = A.omega ?? 0.6, tvRI = L.RI * omega / (1 + ke - omega) / Math.pow(1 + ke, n), roeT = L.NP / L.E0, payT = L.NP > 0 ? Math.min(1, L.Div / L.NP) : 0, gS = Math.min(gT, roeT * (1 - payT));
  const tvDiv = ke > gS ? L.Div * (1 + gS) / (ke - gS) / Math.pow(1 + ke, n) : null, E0 = P[0].E0;
  const ri = (E0 + pvRI + tvRI) / sh, ddm = isNum(tvDiv) ? (pvDiv + tvDiv) / sh : null, jpb = ke > gS ? (roeT - gS) / (ke - gS) : null;
  return {ri, ddm, jpb, jpbVal: isNum(jpb) ? jpb * E0 / sh : null, pvRI, tvRI, pvDiv, tvDiv, roeT, gS};
}
