  const n = Math.max(3, Math.min(10, Math.round(a.years))), P = []; let A0 = a.assets, D0 = a.dep, L0 = a.loans, E0 = a.eq; const kCap = isNum(a.car0) && a.car0 > 0 ? (a.car0 / 100) / (a.eq / (a.rwa / 100 * a.assets)) : 1;
